import java.util.*;

class Solution {
  public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
    Set<String> words = new HashSet<>(wordList);
    List<List<String>> ans = new ArrayList<>();
    if (!words.contains(endWord)) return ans;
    // BFS level by level, recording for each word the words one level up that reach it
    Map<String, List<String>> parents = new HashMap<>();
    Set<String> level = new HashSet<>(Collections.singleton(beginWord));
    words.remove(beginWord);
    boolean found = false;
    while (!level.isEmpty() && !found) {
      Set<String> next = new HashSet<>();
      for (String w : level) words.remove(w);
      for (String w : level) {
        char[] chars = w.toCharArray();
        for (int i = 0; i < chars.length; i++) {
          char orig = chars[i];
          for (char c = 'a'; c <= 'z'; c++) {
            if (c == orig) continue;
            chars[i] = c;
            String cand = new String(chars);
            if (words.contains(cand)) {
              next.add(cand);
              parents.computeIfAbsent(cand, k -> new ArrayList<>()).add(w);
              if (cand.equals(endWord)) found = true;
            }
          }
          chars[i] = orig;
        }
      }
      level = next;
    }
    if (!found) return ans;
    LinkedList<String> path = new LinkedList<>();
    path.add(endWord);
    backtrack(endWord, beginWord, parents, path, ans);
    return ans;
  }

  private void backtrack(String word, String begin, Map<String, List<String>> parents, LinkedList<String> path, List<List<String>> ans) {
    if (word.equals(begin)) {
      ans.add(new ArrayList<>(path));
      return;
    }
    for (String p : parents.getOrDefault(word, Collections.emptyList())) {
      path.addFirst(p);
      backtrack(p, begin, parents, path, ans);
      path.removeFirst();
    }
  }
}
